theorem seq_step_ctx {c₁ c₁' c₂ : Cmd} {s s' : Env}
    (h : SmallStep (c₁, s) (c₁', s')) :
    SmallStep (.seq c₁ c₂, s) (.seq c₁' c₂, s')

theorem smallstep_final_unique {c : Cmd} {s t t' : Env}
    (h1 : (c, s) = (.skip, t) ∨ SmallStep (c, s) (.skip, t))
    (h2 : (c, s) = (.skip, t') ∨ SmallStep (c, s) (.skip, t')) : t = t'
